<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { gsap } from 'gsap';
const props = defineProps<{ reducedMotion: boolean; homeImage: string; titleImage: string; paperImage: string; doorImage: string }>();
const emit = defineEmits<{ finish: [] }>();
const scroller = ref<HTMLElement>();
const progress = ref(0), pointer = ref({ x: 0, y: 0 }), door = ref(0), dragging = ref(false), done = ref(false);
let startX = 0, distance = 0;
const phoneView = ref<'lock' | 'calendar' | 'resume' | 'chat'>('lock');
const reply = ref('好，我这两天回来。'), sentReply = ref(''), bookOpen = ref(false), theme = ref(0), knocked = ref(false);
const themes = [
 { title: '寻味街巷', word: '味', text: '替奶奶走访几家小店，问一问包子的馅、面馆的汤，补上旧食谱空着的几页。' },
 { title: '人情冷暖', word: '情', text: '灶边的父女、赶着做活的熟客、等一份晚饭的人。听他们说，也试着帮一点忙。' },
 { title: '人生百味', word: '归', text: '你是暂时失业、回到故乡的小满。在别人的日子里，慢慢接着过自己的生活。' },
];
const act = computed(() => Math.min(4, Math.floor(progress.value + .48)));
watch(act, () => { phoneView.value = 'lock'; });
const beats = [
 { n: '序', place: '百味录', title: '从一碗热饭说起。', copy: '你将成为暂时失业、回到故乡的小满。', extra: '替奶奶寻访几家小店，补一本旧食谱。问的是一餐一饭，遇见的是各自过日子的人。' },
 { n: '一', place: '城市 / 星期一', title: '今天，不用赶早班。', copy: '离开公司的东西，一个纸箱就装完了。', extra: '' },
 { n: '二', place: '傍晚 / 家里的消息', title: '“被子给你晒好了。”', copy: '奶奶没有问工作，只问什么时候回来。', extra: '我把“最近不太顺”删掉，换成了一句：“这两天回来。”' },
 { n: '三', place: '归途 / 窗边', title: '先回去住几天。', copy: '窗外的楼慢慢低了，手机的信号断了一会儿。', extra: '简历没写完。可这次，我没有再把车票改到下个星期。' },
 { n: '四', place: '长明巷 / 家门口', title: '“小满？门没锁。”', copy: '箱子先放门边。屋里有人在等。', extra: '' },
];
function scroll() { const el = scroller.value; if (el) progress.value = el.scrollTop / el.clientHeight; }
// Native focus can scroll sticky descendants to their original layout position.
// Restore the last reading position before that scroll changes the active act.
function preserveScenePosition() {
 const el=scroller.value;if(!el)return;
 const top=progress.value*el.clientHeight;
 if(Math.abs(el.scrollTop-top)>1)el.scrollTo({top,behavior:'instant'});
}
function point(e: PointerEvent) { if (!props.reducedMotion && e.pointerType !== 'touch') pointer.value = { x: (e.clientX / innerWidth - .5) * 2, y: (e.clientY / innerHeight - .5) * 2 }; }
function animateDoor(value: number, duration = .45) { gsap.to(door, { value, duration: props.reducedMotion ? 0 : duration, ease: 'power3.out', overwrite: true }); }
function grab(e: PointerEvent) { if (done.value) return; startX = e.clientX; distance = 0; dragging.value = true; gsap.killTweensOf(door); (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId); }
function pull(e: PointerEvent) { if (dragging.value) { distance = startX - e.clientX; animateDoor(Math.max(0, Math.min(.98, distance / Math.min(300, innerWidth * .6))), .13); } }
