function finish() { if (done.value) return; done.value = true; animateDoor(1, 1.15); timer = setTimeout(() => emit('finish'), props.reducedMotion ? 0 : 1700); }
function release() { dragging.value = false; if (distance > Math.min(85, innerWidth * .2)) finish(); else if (Math.abs(distance) < 6) { if (knocked.value) finish(); else { knocked.value = true; animateDoor(.12, .8); } } else animateDoor(knocked.value ? .12 : 0, .7); }
