function keyboard(e: KeyboardEvent) { if (e.target !== scroller.value) return; if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); if (act.value === 4) finish(); else scroller.value?.scrollTo({ top: (act.value + 1) * scroller.value.clientHeight, behavior: props.reducedMotion ? 'instant' : 'smooth' }); } }
onBeforeUnmount(() => { clearTimeout(timer); gsap.killTweensOf(door); });
