<template>
 <section ref="scroller" class="journey" :class="{ still: reducedMotion, complete: done, 'door-dragging': dragging }" tabindex="0" aria-label="归乡引子，滚动阅读；回车进入下一幕" @scroll.passive="scroll" @focusin="preserveScenePosition" @pointermove="point" @keydown="keyboard" :style="{ '--progress': progress, '--mx': pointer.x, '--my': pointer.y, '--door': door, '--paper': `url(${paperImage})`, '--door-art': `url(${doorImage})` }">
  <div class="journey-sticky" :data-act="act">
   <div class="journey-world" aria-hidden="true">
