   </div>
   <div v-else class="journey-editorial" :key="act"><span class="journey-number">{{ beats[act]!.n }}</span><h2>{{ beats[act]!.title }}</h2><p>{{ beats[act]!.copy }}</p><p v-if="beats[act]!.extra" class="journey-thought">{{ beats[act]!.extra }}</p></div>
   <div class="journey-objects">
