     <button class="recipe-cover" :aria-expanded="bookOpen" aria-controls="intro-theme-page" aria-label="翻开百味录" @click="bookOpen = !bookOpen"><span class="cover-stitches"><i v-for="n in 6" :key="n"></i></span><span class="recipe-inner"><small>家 常 手 记</small><h3>百味录</h3><p>米酒 · 清汤 · 热饭</p><span class="recipe-stamp">长明<br>巷藏</span></span></button><div class="recipe-leaf" aria-hidden="true"></div>
    </div>
