    <div class="journey-phone" :class="{ visible: act === 1 || act === 2, messaging: act === 2, 'phone-engaged': phoneView !== 'lock' }" :inert="act !== 1 && act !== 2"><div class="phone-metal"><div class="phone-volume"></div><button class="phone-power" aria-label="锁定手机" @click="phoneView = 'lock'"></button><div class="phone-glass"><span class="phone-island"><i></i></span><div class="device-status"><span>{{ act === 1 ? '09:41' : '18:26' }}</span><span aria-hidden="true">▮▮▮ ◒ ▰</span></div>
